    description: { de: "Die Rocky Mountains sind ein riesiges Gebirgssystem im Westen Nordamerikas.", hu: "A Sziklás-hegység hatalmas hegységrendszer Észak-Amerika nyugati részén.", ro: "Munții Stâncoși sunt un sistem muntos vast din vestul Americii de Nord.", en: "The Rocky Mountains are a vast mountain system in western North America." , es: "Las Montañas Rocosas son un enorme sistema montañoso en el oeste de América del Norte.", pt: "As Montanhas Rochosas são um enorme sistema montanhoso no oeste da América do Norte.", fr: "Les Montagnes Rocheuses sont un immense système montagneux dans l'ouest de l'Amérique du Nord."},
    descriptionAdvanced: {
      de: "Die Rocky Mountains, auch Rockies genannt, sind ein gewaltiges Hochgebirgssystem im Westen Nordamerikas, das sich über 4.800 Kilometer von British Columbia in Kanada bis nach New Mexico in den USA erstreckt. Sie bilden die kontinentale Wasserscheide, die bestimmt, ob Flüsse in den Atlantik oder den Pazifik fließen. Der höchste Gipfel des Gebirges ist der Mount Elbert in Colorado mit einer Höhe von 4.401 Metern. Die geologische Entstehung der Rockies begann vor etwa 80 bis 55 Millionen Jahren während der Laramischen Gebirgsbildung, als tektonische Platten begannen, das Land emporzuheben. Heute beherbergt das Gebirge zahlreiche Nationalparks, wie den Banff-Nationalpark in Kanada und den Rocky-Mountain-Nationalpark in den USA, die für ihre spektakuläre Flora und Fauna bekannt sind. Das Gebirge ist nicht nur ein bedeutendes Reservoir für Süßwasser, sondern auch reich an Bodenschätzen wie Gold, Silber und Kupfer.",
      hu: "A Sziklás-hegység Észak-Amerika nyugati részének legmeghatározóbb hegyvonulata, amely több mint 4800 kilométer hosszan húzódik a kanadai Brit Columbiától az amerikai Új-Mexikó államig. Ez a hegylánc alkotja a kontinentális vízválasztót, amely eldönti, hogy a folyók az Atlanti- vagy a Csendes-óceánba torkollanak-e. Legmagasabb pontja a Coloradóban található Mount Elbert, amely 4401 méterrel magasodik a tengerszint fölé. A hegység kialakulása körülbelül 80-55 millió évvel ezelőtt kezdődött a laramid hegységképződés során, amikor a tektonikus lemezek mozgása megemelte a felszínt. A térség ma számos világhírű nemzeti parknak ad otthont, mint például a Banff vagy a Jasper Kanada területén. A hegység nemcsak lenyűgöző természeti értékekben gazdag, hanem hatalmas ásványkincs-tartalékokkal, például arannyal, ezüsttel és rézzel is rendelkezik.",
      ro: "Munții Stâncoși reprezintă un lanț muntos vast din vestul Americii de Nord, întinzându-se pe o lungime de peste 4.800 de kilometri, din Columbia Britanică (Canada) până în New Mexico (SUA). Aceștia formează Diviziunea Continentală, linia care separă bazinele hidrografice ce se varsă în Oceanul Atlantic de cele ce curg spre Oceanul Pacific. Cel mai înalt vârf este Mount Elbert din statul Colorado, atingând o altitudine de 4.401 metri. Formarea geologică a munților a început în urmă cu aproximativ 80 până la 55 de milioane de ani, în timpul orogenezei Laramide. Regiunea adăpostește numeroase parcuri naționale celebre, cum ar fi Parcul Național Rocky Mountain din SUA sau Parcul Național Banff din Canada, protejând specii emblematice precum ursul grizzly și elanul. Pe lângă valoarea ecologică, munții sunt o sursă majoră de resurse naturale, inclusiv cupru, aur și gaze naturale.",
      en: "The Rocky Mountains, often called the Rockies, are a massive mountain range in western North America, stretching more than 3,000 miles from British Columbia in Canada to New Mexico in the United States. They form the Continental Divide, which determines the flow of water toward either the Atlantic or Pacific Oceans. The highest peak in the entire system is Mount Elbert in Colorado, reaching an elevation of 14,440 feet. The geological formation of the Rockies began between 80 and 55 million years ago during the Laramide orogeny, characterized by intense tectonic activity. Today, the range hosts numerous world-renowned protected areas, such as Banff and Jasper National Parks in Canada and Rocky Mountain National Park in the US. Beyond their scenic beauty and biodiversity, the Rockies are a crucial source of freshwater and contain vast deposits of minerals like gold, silver, and molybdenum.",
      es: "La región es un lugar destacado que impresiona por una fascinante mezcla de historia, economía moderna y profundidad cultural. Los visitantes aprecian la alta calidad de vida, la infraestructura innovadora y las diversas opciones de ocio. Este lugar desempeña un papel crucial en el crecimiento económico y atrae a profesionales de numerosas disciplinas. Con una arquitectura distintiva y un fuerte sentido de comunidad, este lugar combina los valores tradicionales con las exigencias de un mundo globalizado, convirtiéndose en una parte indispensable de la identidad regional y atrayendo continuamente nueva vida e impulsos económicos a los alrededores.",
      pt: "A região é um local significativo que se destaca por uma mistura fascinante de história, economia moderna e profundidade cultural. Os visitantes apreciam a alta qualidade de vida, a infraestrutura inovadora e as diversas opções de lazer. Este local desempenha um papel crucial no crescimento económico e serve como um ponto de atração para profissionais de diversas disciplinas. Com uma arquitetura distinta e um forte sentido de comunidade, este lugar combina valores tradicionais com as exigências de um mundo globalmente ligado, tornando-se uma parte indispensável da identidade regional e atraindo continuamente nova vida e impulsos económicos para os arredores.",
      fr: "La région est un site majeur qui séduit par un mélange fascinant d'histoire, d'économie moderne et de profondeur culturelle. Les visiteurs apprécient la qualité de vie élevée, les infrastructures innovantes et les multiples possibilités de loisirs. Ce lieu joue un rôle crucial dans la croissance économique et attire des professionnels de nombreuses disciplines. Avec une architecture marquée et un fort sentiment de communauté, ce lieu allie valeurs traditionnelles et exigences d'un monde connecté à l'échelle mondiale, ce qui en fait un élément indispensable de l'identité régionale, attirant continuellement une nouvelle vie et des impulsions économiques dans les environs.",
    },
