      ro: ["Versanți muntoși foarte abrupți.", "Popular pentru sporturi de iarnă.", "Sursă de apă pentru Salt Lake City.", "Din punct de vedere geologic activ.", "Regiune importantă de drumeție.", "Diferențe mari de altitudine."],
      en: ["Very steep mountain slopes.", "Popular for winter sports.", "Water source for Salt Lake City.", "Geologically active.", "Important hiking region.", "Large elevation differences."],
      es: ["Laderas de montaña muy empinadas.", "Popular para deportes de invierno.", "Fuente de agua para Salt Lake City.", "Geológicamente activa.", "Importante región de senderismo.", "Grandes diferencias de altitud."],
      pt: ["Encostas de montanha muito íngremes.", "Popular para desportos de inverno.", "Fonte para Salt Lake City.", "Geologicamente ativa.", "Importante região de caminhadas.", "Grandes diferenças de altitude."],
