      hu: ["A Grand Teton Nemzeti Park része.", "Nagyon meredek, fiatal geológiai szerkezet.", "Látványos alpesi csúcsok.", "Túrázásról híres.", "Gleccserek a magasságokban.", "Fontos turisztikai célpont."],
