    description: { de: "Ein tiefes Wüstenbecken und einer der heißesten Orte der Erde.", hu: "Mély sivatagi medence és a Föld egyik legforróbb helye.", ro: "Un bazin deșertic adânc și unul dintre cele mai fierbinți locuri de pe Pământ.", en: "A deep desert basin and one of the hottest places on Earth." , es: "Una profunda cuenca desértica y uno de los lugares más calurosos de la Tierra.", pt: "Uma bacia desértica profunda e um dos lugares mais quentes da Terra.", fr: "Un bassin désertique profond et l'un des endroits les plus chauds de la planète."},
    descriptionAdvanced: {
      de: "Death Valley ist ein extremes Wüstenbecken im Osten Kaliforniens und Teil der Mojave-Wüste. Es ist bekannt als der heißeste und trockenste Ort Nordamerikas und beherbergt mit Badwater Basin den tiefsten Punkt des Kontinents, der 86 Meter unter dem Meeresspiegel liegt. Geologisch gesehen ist das Tal ein Grabenbruch, der durch die Dehnung der Erdkruste in der Basin and Range Province entstanden ist. Historisch ist das Gebiet eng mit dem kalifornischen Goldrausch von 1849 verbunden, als eine Gruppe von Siedlern dort fast verhungerte, was dem Tal seinen Namen gab. Später wurde es durch den Abbau von Borax durch die berühmten 20-Maultier-Gespanne wirtschaftlich bedeutend. Trotz der lebensfeindlichen Bedingungen beherbergt das Tal eine erstaunliche Vielfalt an Lebewesen, darunter die seltenen Wüsten-Puppfische und Dickhornschafe. Der 1994 gegründete Death Valley National Park schützt diese einzigartige geologische und ökologische Landschaft, die durch bizarre Salzpfannen, Sanddünen und farbenprächtige Canyons besticht.",
      hu: "A Death Valley (Halál-völgy) Kalifornia keleti részén, a Mojave-sivatagban található extrém sivatagi medence. Észak-Amerika legforróbb és legszárazabb helyeként ismert, itt található a kontinens legmélyebb pontja is, a Badwater-medence, amely 86 méterrel fekszik a tengerszint alatt. Geológiailag a völgy egy árokrendszer, amely a földkéreg tágulása következtében jött létre a Basin and Range tartományban. Történelmileg a terület szorosan kapcsolódik az 1849-es kaliforniai aranylázhoz, amikor egy csapat bevándorló eltévedt a völgyben, és egyikük távozáskor elköszönt a 'Halál völgyétől', innen ered a név. Később a bórax bányászata vált jelentőssé, amelyet a híres 20 öszvérből álló fogatokkal szállítottak. A zord körülmények ellenére a terület gazdag élővilággal rendelkezik, például itt él a ritka sivatagi fogasponty és a kanadai vadjuh. Az 1994-ben létrehozott Death Valley Nemzeti Park védi ezt az egyedülálló tájat, amely sómezőiről, homokdűnéiről és színes kanyonjairól híres.",
      ro: "Death Valley este un bazin deșertic extrem situat în estul Californiei, făcând parte din Deșertul Mojave. Este recunoscut drept cel mai fierbinte și uscat loc din America de Nord, găzduind Badwater Basin, punctul situat la cea mai joasă altitudine de pe continent, la 86 de metri sub nivelul mării. Din punct de vedere geologic, valea este o groapă tectonică formată prin extensia scoarței terestre. Istoria locului este marcată de goana după aur din 1849, când un grup de coloniști a rămas blocat aici, dând văii numele sumbru de astăzi. Ulterior, zona a devenit celebră pentru extracția boraxului, transportat de legendarele atelaje cu 20 de muli. În ciuda condițiilor aride, ecosistemul include specii adaptate, precum peștii pupfish și oile bighorn. Parcul Național Death Valley, înființat în 1994, conservă acest peisaj spectaculos format din întinderi de sare, dune de nisip și canioane colorate.",
      en: "Death Valley is an extreme desert basin in eastern California, part of the Mojave Desert. It holds the record for the highest air temperature ever recorded on Earth and features Badwater Basin, the lowest point in North America at 86 meters below sea level. Geologically, the valley is a graben formed by the stretching of the Earth's crust within the Basin and Range Province. Its name originates from the 1849 Gold Rush, when a group of pioneers narrowly escaped with their lives after becoming trapped in the arid wilderness. The valley later gained economic fame for borax mining, famously transported by '20-mule teams.' Despite its name, Death Valley supports a surprising diversity of life, including the endemic Devils Hole pupfish and desert bighorn sheep. Designated as a National Park in 1994, the area preserves a stunning landscape of salt flats, shifting sand dunes, and vibrant geological formations like Artist's Drive.",
      es: "La región es una ubicación importante que cautiva con una fascinante mezcla de historia, economía moderna y profundidad cultural. Los visitantes aprecian la alta calidad de vida, la infraestructura innovadora y las diversas opciones de ocio. Este lugar desempeña un papel crucial en el crecimiento económico y actúa como un centro de atracción para profesionales de numerosas disciplinas. Con una arquitectura distintiva y un fuerte sentido de comunidad, este lugar combina valores tradicionales con las exigencias de un mundo globalmente conectado, lo que lo convierte en una parte indispensable de la identidad regional y atrae continuamente nueva vida e impulsos económicos a los alrededores.",
      pt: "A região é um local significativo que cativa com uma mistura fascinante de história, economia moderna e profundidade cultural. Os visitantes apreciam a elevada qualidade de vida, a infraestrutura inovadora e as diversas opções de lazer. Este local desempenha um papel crucial no crescimento económico e serve como um centro de atração para profissionais de inúmeras disciplinas. Com uma arquitetura distinta e um forte sentido de comunidade, este lugar combina valores tradicionais com as exigências de um mundo globalmente conectado, tornando-o uma parte indispensável da identidade regional e atraindo continuamente nova vida e impulsos económicos para as áreas circundantes.",
      fr: "La région est un site important qui séduit par un mélange fascinant d'histoire, d'économie moderne et de profondeur culturelle. Les visiteurs apprécient la haute qualité de vie, l'infrastructure innovante et les diverses possibilités de loisirs. Ce lieu joue un rôle crucial dans la croissance économique et sert de pôle d'attraction pour les professionnels de nombreuses disciplines. Avec une architecture marquée et un fort sentiment de communauté, ce lieu allie valeurs traditionnelles et exigences d'un monde globalement connecté, ce qui en fait un élément indispensable de l'identité régionale et apporte continuellement une nouvelle vie ainsi que des impulsions économiques aux environs.",
    },
