      de: ["Das Badwater Basin liegt offiziell 86 Meter unter dem Meeresspiegel.", "Im Jahr 1913 wurde hier mit 56,7 °C die höchste Lufttemperatur der Erde gemessen.", "Der Death Valley National Park erstreckt sich über ca. 13.650 Quadratkilometer.", "Die berühmten 'wandernden Steine' befinden sich auf der Racetrack Playa.", "Borax wurde ab den 1880er Jahren industriell im Tal abgebaut.", "Es fallen durchschnittlich weniger als 60 mm Niederschlag pro Jahr."],
